Method.Implementation:

 // Script to clean the Globals which are used by two components
 // Sh-Ttc-Delim_Text-TRANSTRACKCLAIMDBLOAD and Sh-Ttc-Demin_Text_TRANSTRACK_RETRY
 // ^TransTrackingLoad contains entries with date as value
 // ^TransTrackingNotFound contains number of retries
 // Delete based on date
   SET k=$ORDER(^TransTrackingLoad(""))
   WHILE (k'="") {
	 set val = ^TransTrackingLoad(k)
     WRITE k _ ", " _ val _ "Diff: " _ $PIECE($HOROLOG,",",1) - $PIECE($ZDATETIMEH(val,5),",",1), !
     // Get next subscript 
     if ($L(val) > 5)
     {
     	 // Check if entry is older than 1 day
	     if ( ($PIECE($HOROLOG,",",1) - $PIECE($ZDATETIMEH(val,5),",",1)) > 1)
	     {
		     Write !, "Found the key: " _ k _ ", delete"
		     KILL ^TransTrackingLoad(k)
	     }
	     if ($GET(^TransTrackingNotFound(k)) '= "")
	     {
	     	WRITE !, "TransTrackingNotFound: "  _ $GET(^TransTrackingNotFound(k))
	     	kill ^TransTrackingNotFound(k)
	     }
     }
     SET k=$ORDER(^TransTrackingLoad(k))
   }
